// 5 dígitos y nada más. Si no, ni se molesta en llamar a Envia.
const cp = String(($json.body || {}).codigo_postal || '').trim();
if (!/^\d{5}$/.test(cp)) {
  return [{ json: { valido: false, motivo: 'cp_invalido', codigo_postal: cp } }];
}
return [{ json: { valido: true, codigo_postal: cp } }];

// Envia ya manda las sucursales ordenadas por distancia al CP. Sólo se recortan a 3
// y se arma lo que el bot le lee al cliente. branch_code es lo que N4 necesita.
const errorEnvia = x => x && x.meta === 'error';

const g = $('Envia · geocodes').first().json;
const datos = Array.isArray(g) ? g[0] : g;
if (errorEnvia(datos)) {
  return [{ json: { ok: false, motivo: 'envia_error', detalle: datos.error } }];
}
const ciudad = (datos && datos.locality) || '';
const estado = (datos && datos.state && datos.state.code && datos.state.code['2digit']) || '';
const cp = $('¿5 dígitos?').first().json.codigo_postal;

// El nodo HTTP parte el array en items; si llegara entero, se aplana igual.
const items = $input.all().map(i => i.json).flat();
if (items.some(errorEnvia)) {
  return [{ json: { ok: false, motivo: 'envia_error', detalle: items.find(errorEnvia).error, codigo_postal: cp } }];
}

const tres = items.filter(s => s && s.branch_code).slice(0, 3).map(s => {
  const a = s.address || {};
  return {
    branch_code: s.branch_code,
    nombre: s.reference,
    direccion: [a.street, a.number, a.city, a.state, a.postalCode].filter(Boolean).join(', '),
    distancia_km: s.distance ?? null,
    mapa: (a.latitude && a.longitude)
      ? `https://www.google.com/maps/search/?api=1&query=${a.latitude},${a.longitude}`
      : null
  };
});

return [{ json: tres.length
  ? { ok: true, codigo_postal: cp, ciudad, estado, sucursales: tres }
  : { ok: false, motivo: 'sin_cobertura', codigo_postal: cp, ciudad, estado } }];
